import torch.nn as nn
from torch.utils.cpp_extension import load_inline
ln_cpp_decl = r'''
#include <torch/extension.h>
torch::Tensor layernorm_forward(torch::Tensor x,
                                torch::Tensor weight,
                                torch::Tensor bias,
                                double eps);
'''
ln_cuda_src = r'''
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>
using namespace cute;
template <int Threads, int Vec>
__global__ void ln_partial_kernel(
    const float* __restrict__ X,
    float* __restrict__ PS,
    float* __restrict__ PQ,
    int64_t L,
    int64_t Nv,
    int64_t tail0,
    int parts,
    int64_t chunk_vec)
{
  const int64_t row = blockIdx.x;
  const int part = blockIdx.y;
  const int tid = threadIdx.x;
  const int64_t row_off = row * L;
  int64_t start = (int64_t)part * chunk_vec;
  int64_t end = start + chunk_vec;
  if (end > Nv) end = Nv;
  const float4* xv = reinterpret_cast<const float4*>(X + row_off);
  float s = 0.0f;
  float q = 0.0f;
  for (int64_t i = start + tid; i < end; i += Threads) {
    float4 v = xv[i];
    s += v.x + v.y + v.z + v.w;
    q += v.x * v.x + v.y * v.y + v.z * v.z + v.w * v.w;
  }
  if (part == 0) {
    for (int64_t i = tail0 + tid; i < L; i += Threads) {
      float v = X[row_off + i];
      s += v;
      q += v * v;
    }
  }
  constexpr int Warps = Threads / 32;
  __shared__ float ws[Warps];
  __shared__ float wq[Warps];
  const int lane = tid & 31;
  const int warp = tid >> 5;
  #pragma unroll
  for (int off = 16; off > 0; off >>= 1) {
    s += __shfl_down_sync(0xffffffffu, s, off);
    q += __shfl_down_sync(0xffffffffu, q, off);
  }
  if (lane == 0) {
    ws[warp] = s;
    wq[warp] = q;
  }
  __syncthreads();
  if (warp == 0) {
    float a = (lane < Warps) ? ws[lane] : 0.0f;
    float b = (lane < Warps) ? wq[lane] : 0.0f;
    #pragma unroll
    for (int off = Warps / 2; off > 0; off >>= 1) {
      a += __shfl_down_sync(0xffffffffu, a, off);
      b += __shfl_down_sync(0xffffffffu, b, off);
    }
    if (lane == 0) {
      const int64_t idx = row * (int64_t)parts + part;
      PS[idx] = a;
      PQ[idx] = b;
    }
  }
}
template <int Threads>
__global__ void ln_stats_kernel(
    const float* __restrict__ PS,
    const float* __restrict__ PQ,
    float* __restrict__ Mean,
    float* __restrict__ Rstd,
    int64_t L,
    int parts,
    float eps)
{
  const int64_t row = blockIdx.x;
  const int tid = threadIdx.x;
  const int64_t base = row * (int64_t)parts;
  float s = 0.0f;
  float q = 0.0f;
  for (int i = tid; i < parts; i += Threads) {
    s += PS[base + i];
    q += PQ[base + i];
  }
  constexpr int Warps = Threads / 32;
  __shared__ float ws[Warps];
  __shared__ float wq[Warps];
  const int lane = tid & 31;
  const int warp = tid >> 5;
  #pragma unroll
  for (int off = 16; off > 0; off >>= 1) {
    s += __shfl_down_sync(0xffffffffu, s, off);
    q += __shfl_down_sync(0xffffffffu, q, off);
  }
  if (lane == 0) {
    ws[warp] = s;
    wq[warp] = q;
  }
  __syncthreads();
  if (tid == 0) {
    float a = 0.0f;
    float b = 0.0f;
    #pragma unroll
    for (int i = 0; i < Warps; ++i) {
      a += ws[i];
      b += wq[i];
    }
    float invL = 1.0f / (float)L;
    float mean = a * invL;
    float var = b * invL - mean * mean;
    var = var < 0.0f ? 0.0f : var;
    Mean[row] = mean;
    Rstd[row] = rsqrtf(var + eps);
  }
}
template <int Threads, int Vec, int RowsPerCTA>
__global__ void ln_norm_kernel(
    const float* __restrict__ X,
    const float* __restrict__ G,
    const float* __restrict__ B,
    const float* __restrict__ Mean,
    const float* __restrict__ Rstd,
    float* __restrict__ Y,
    int64_t rows,
    int64_t L,
    int64_t Nv,
    int64_t tail0,
    int64_t chunk_vec)
{
  const int part = blockIdx.y;
  const int64_t row0 = (int64_t)blockIdx.x * RowsPerCTA;
  const int tid = threadIdx.x;
  int64_t start = (int64_t)part * chunk_vec;
  int64_t end = start + chunk_vec;
  if (end > Nv) end = Nv;
  const int64_t nvec = end - start;
  extern __shared__ __align__(16) unsigned char smem_raw[];
  float4* sG = reinterpret_cast<float4*>(smem_raw);
  float4* sB = sG + chunk_vec;
  const float4* gv = reinterpret_cast<const float4*>(G);
  const float4* bv = reinterpret_cast<const float4*>(B);
  for (int64_t j = tid; j < nvec; j += Threads) {
    sG[j] = gv[start + j];
    sB[j] = bv[start + j];
  }
  __syncthreads();
  #pragma unroll
  for (int r = 0; r < RowsPerCTA; ++r) {
    const int64_t row = row0 + r;
    if (row >= rows) break;
    const int64_t row_off = row * L;
    const float4* xv = reinterpret_cast<const float4*>(X + row_off);
    float4* yv = reinterpret_cast<float4*>(Y + row_off);
    const float mean = Mean[row];
    const float rstd = Rstd[row];
    for (int64_t j = tid; j < nvec; j += Threads) {
      const int64_t i = start + j;
      float4 x4 = xv[i];
      float4 g4 = sG[j];
      float4 b4 = sB[j];
      float4 o4;
      o4.x = (x4.x - mean) * rstd * g4.x + b4.x;
      o4.y = (x4.y - mean) * rstd * g4.y + b4.y;
      o4.z = (x4.z - mean) * rstd * g4.z + b4.z;
      o4.w = (x4.w - mean) * rstd * g4.w + b4.w;
      yv[i] = o4;
    }
    if (part == 0) {
      for (int64_t i = tail0 + tid; i < L; i += Threads) {
        Y[row_off + i] = (X[row_off + i] - mean) * rstd * G[i] + B[i];
      }
    }
  }
}
torch::Tensor layernorm_forward(torch::Tensor x,
                                torch::Tensor weight,
                                torch::Tensor bias,
                                double eps)
{
  TORCH_CHECK(x.is_cuda() && weight.is_cuda() && bias.is_cuda());
  TORCH_CHECK(x.scalar_type() == at::kFloat &&
              weight.scalar_type() == at::kFloat &&
              bias.scalar_type() == at::kFloat);
  auto x_c = x.contiguous();
  auto w_c = weight.contiguous();
  auto b_c = bias.contiguous();
  const int64_t L = w_c.numel();
  TORCH_CHECK(L > 0);
  TORCH_CHECK(b_c.numel() == L);
  TORCH_CHECK(x_c.numel() % L == 0);
  const int64_t rows = x_c.numel() / L;
  auto y = torch::empty_like(x_c);
  constexpr int Threads = 256;
  constexpr int Vec = 4;
  constexpr int RowsPerCTA = 4;
  const int64_t Nv = L / Vec;
  const int64_t tail0 = Nv * Vec;
  const int64_t target = (int64_t)Threads * Vec * 6;
  int64_t parts64 = (L + target - 1) / target;
  if (parts64 < 1) parts64 = 1;
  if (parts64 > 1024) parts64 = 1024;
  const int parts = (int)parts64;
  int64_t chunk_vec = 0;
  if (Nv > 0) chunk_vec = (Nv + parts64 - 1) / parts64;
  auto opts = x_c.options();
  auto ps = torch::empty({rows * parts64}, opts);
  auto pq = torch::empty({rows * parts64}, opts);
  auto mean = torch::empty({rows}, opts);
  auto rstd = torch::empty({rows}, opts);
  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
  dim3 pgrid((unsigned)rows, (unsigned)parts);
  dim3 block(Threads);
  ln_partial_kernel<Threads, Vec><<<pgrid, block, 0, stream>>>(
      x_c.data_ptr<float>(),
      ps.data_ptr<float>(),
      pq.data_ptr<float>(),
      L, Nv, tail0, parts, chunk_vec);
  ln_stats_kernel<Threads><<<dim3((unsigned)rows), block, 0, stream>>>(
      ps.data_ptr<float>(),
      pq.data_ptr<float>(),
      mean.data_ptr<float>(),
      rstd.data_ptr<float>(),
      L, parts, (float)eps);
  const int64_t row_blocks = (rows + RowsPerCTA - 1) / RowsPerCTA;
  dim3 ngrid((unsigned)row_blocks, (unsigned)parts);
  const size_t norm_smem =
      (Nv > 0) ? (size_t)2 * (size_t)chunk_vec * sizeof(float4) : (size_t)0;
  ln_norm_kernel<Threads, Vec, RowsPerCTA><<<ngrid, block, norm_smem, stream>>>(
      x_c.data_ptr<float>(),
      w_c.data_ptr<float>(),
      b_c.data_ptr<float>(),
      mean.data_ptr<float>(),
      rstd.data_ptr<float>(),
      y.data_ptr<float>(),
      rows, L, Nv, tail0, chunk_vec);
  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, cudaGetErrorString(err));
  return y;
}
'''
layernorm_ext = load_inline(
    name='cute_layernorm_ext',
    cpp_sources=ln_cpp_decl,
    cuda_sources=ln_cuda_src,
    functions=['layernorm_forward'],
    extra_cflags=['-O3'],
    extra_cuda_cflags=['-O3'],
    extra_include_paths=[
        '/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include',
        '/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include/cute/',
    ],
    verbose=False,
)
class ModelNew(nn.Module):
    def __init__(self, normalized_shape) -> None:
        super().__init__()
        if isinstance(normalized_shape, int):
            normalized_shape = (normalized_shape,)
        self.normalized_shape = tuple(normalized_shape)
        self.eps = 1e-5
        self.weight = nn.Parameter(torch.ones(self.normalized_shape))
        self.bias = nn.Parameter(torch.zeros(self.normalized_shape))
        self._ext = layernorm_ext
    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self._ext.layernorm_forward(
            x.contiguous(),
            self.weight.contiguous(),
            self.bias.contiguous(),
            float(self.eps),
        )

